import secrets
import hmac
import hashlib
from fastapi import Request, HTTPException, status
from starlette.middleware.base import BaseHTTPMiddleware
from server.config import config

CSRF_SECRET = getattr(config, 'CSRF_SECRET', 'csrf_secret_salt_key_default')
SAFE_METHODS = {'GET', 'HEAD', 'OPTIONS', 'TRACE'}
EXEMPT_PATHS = {'/api/auth/login', '/api/auth/register', '/api/auth/logout', '/api/extension/sync', '/docs', '/openapi.json', '/health'}

def generate_csrf_token() -> str:
    return secrets.token_urlsafe(32)

class CSRFProtectionMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        if request.method in SAFE_METHODS or any(request.url.path.startswith(p) for p in EXEMPT_PATHS):
            response = await call_next(request)
            return response

        csrf_header = request.headers.get('X-CSRF-Token')
        csrf_cookie = request.cookies.get('helpotron_csrf')

        if not csrf_header or not csrf_cookie or not hmac.compare_digest(csrf_header, csrf_cookie):
            # Check if request has valid Bearer token (Bearer token APIs are CSRF-exempt)
            auth_header = request.headers.get('Authorization', '')
            if not auth_header.startswith('Bearer '):
                raise HTTPException(
                    status_code=status.HTTP_403_FORBIDDEN,
                    detail='CSRF token validation failed'
                )

        return await call_next(request)

