    current_user: User = Depends(get_current_authenticated_user),
    db: Session = Depends(get_db)
):
    secret = getattr(current_user, 'two_factor_secret', None)
    if not secret:
        raise HTTPException(status_code=400, detail='Two-factor authentication not set up for this account')

    totp = pyotp.TOTP(secret)
    # Validates current code with a valid_window of 1 step (30s tolerance) to prevent clock drift issues
    if not totp.verify(code, valid_window=1):
        raise HTTPException(status_code=401, detail='Invalid two-factor authentication code')

    return {'verified': True}

