async function syncAssignmentToHelpotron(assignmentData) {
  const { sessionToken } = await chrome.storage.local.get(['sessionToken']);
  if (!sessionToken) {
    throw new Error('User not logged into Helpotron');
  }

  const response = await fetch('https://helpotron.com/api/extension/sync', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${sessionToken}`
    },
    body: JSON.stringify(assignmentData)
  });
  return response.json();
}
